LANG_CODES=('en','hi','mr','es','fr','de','ja','zh','pt','ru','ar','bn','ta','te')
# The original catalog already translates these generic labels accurately.
from ui.strings import t

def v2t(key,language='en'):
    if key in {'test','unit'}:
        return t('lab_col_name' if key=='test' else 'lab_col_unit',language)
    if key=='offline_heading': key='view'
    row=KEYS[key]
    return row[LANG_CODES.index(language)] if language in LANG_CODES else row[0]

assert all(len(v)==len(LANG_CODES) for v in KEYS.values())
